// SPI Serial-to-Parallel interface

module spi_s2p
  import spi_device_pkg::*;
(
  input clk_i,
  input rst_ni, // inverted CSb input

  // SPI data
  input [3:0] s_i,

  // to following logic
  output logic               data_valid_o,
  output spi_byte_t          data_o,
  output logic [BitCntW-1:0] bitcnt_o, // up to 256B payload

  // Configuration
