      .rst_ni,
      .req_i(calc_req_i),
      .operand_a_i({muxed_addr_key[DataWidth +: AddrPadWidth], addr_i}),
      .operand_b_i(muxed_addr_key[DataWidth-1:0]),
      .ack_o(calc_ack_o),
      .prod_o(mask_o)
